+-- A successful direct videos.list response may establish that a known public
+-- resource is no longer accessible. Playlist omission alone never calls this.
+CREATE OR REPLACE FUNCTION tdf_mark_video_unavailable(source_id bigint, run_key uuid,
+  video_id text, reason text, verified timestamptz)
+RETURNS text LANGUAGE plpgsql AS $$
+DECLARE resource record_external_resource%ROWTYPE;
+BEGIN
+  IF reason NOT IN ('nonpublic','not_publicly_accessible') OR verified IS NULL THEN
+    RAISE EXCEPTION 'invalid availability evidence';
+  END IF;
+  PERFORM pg_advisory_xact_lock(20260920, source_id::integer);
+  PERFORM 1 FROM social_sync_account a JOIN records_ingestion_control c ON c.singleton
+    JOIN catalog_backfill_run b ON b.id=run_key
+    WHERE a.id=source_id AND c.enabled AND a.platform='youtube'
+      AND a.records_ingestion->>'enabled'='true'
+      AND nullif(a.records_ingestion->>'approvalReference','') IS NOT NULL
+      AND a.records_ingestion->>'approvedAt' IS NOT NULL
+      AND b.status='running' AND NOT b.dry_run
+      AND b.report::jsonb->>'sourceAccountId'=source_id::text
+    FOR SHARE OF a,c,b;
+  IF NOT FOUND THEN RAISE EXCEPTION 'unapproved availability write'; END IF;
+  SELECT * INTO resource FROM record_external_resource
+    WHERE source_account_id=source_id AND external_code=video_id AND resource_kind='video'
+    FOR UPDATE;
+  IF NOT FOUND THEN RETURN 'unknown'; END IF;
+  IF resource.verified_at >= verified THEN RETURN 'stale'; END IF;
+  IF resource.availability='unavailable' AND resource.availability_reason=reason THEN
+    UPDATE record_external_resource SET verified_at=verified WHERE id=resource.id;
+    RETURN 'unchanged';
+  END IF;
+  PERFORM tdf_clear_owned_video_metadata(resource.id);
+  -- Do not retain a private provider description or thumbnail. The stable
+  -- identity, editorial membership and independent artwork remain auditable.
+  UPDATE record_external_resource SET availability='unavailable', availability_reason=reason,
+    verified_at=verified,
+    thumbnail_url=CASE WHEN thumbnail_url=resource.provider_metadata->>'thumbnailUrl'
+      OR thumbnail_url ~ ('^https://i[.]ytimg[.]com/vi(_webp)?/'||video_id||'/')
+      THEN NULL ELSE thumbnail_url END,
+    version=version+1,updated_at=now() WHERE id=resource.id;
+  INSERT INTO records_ingestion_change(run_id,resource_id,source_account_id,action,before_value,after_value)
+    VALUES(run_key,resource.id,source_id,'unavailable',
+      jsonb_build_object('availability',resource.availability),
+      jsonb_build_object('externalCode',video_id,'reason',reason));
+  RETURN 'unavailable';
+END $$;
+
+-- Configuration changes and ingestion use the same source lock. A busy source
+-- fails promptly instead of allowing an in-flight response to use new approval.
+CREATE OR REPLACE FUNCTION tdf_lock_records_source_configuration()
+RETURNS trigger LANGUAGE plpgsql AS $$
+BEGIN
+  IF (NEW.records_ingestion - 'lastAttemptAt') IS DISTINCT FROM (OLD.records_ingestion - 'lastAttemptAt')
+    OR NEW.party_id IS DISTINCT FROM OLD.party_id
+    OR NEW.artist_profile_id IS DISTINCT FROM OLD.artist_profile_id THEN
+    IF NOT pg_try_advisory_xact_lock(20260920, OLD.id::integer) THEN
+      RAISE EXCEPTION 'records source is busy' USING ERRCODE='55P03';
+    END IF;
